**Exercice 3** (10 points)

Le gestionnaire du parking d'un marché de Bafoussam automatise le calcul de la recette de la matinée. Le tarif est de 300 FCFA l'heure jusqu'à 4 heures de stationnement, puis de 200 FCFA par heure supplémentaire. Le programme C suivant enregistre cinq véhicules et leur durée de stationnement (de 1 à 24 heures).

```c
 1  #include <stdio.h>
 2  #include <string.h>
 3  #define N 5
 4  #define TARIF 300
 5
 6  typedef struct {
 7      char plaque[10];
 8      int heures;
 9      int montant;
10  } Vehicule;
11
12  Vehicule parc[N];
13  int recette = 0;
14
15  int calculer(int h) {
16      int m;
17      if (h <= 1)
18          m = TARIF;
19      else if (h <= 4)
20          m = TARIF * h;
21      else
22          m = TARIF * 4 + 200 * (h - 4);
23      return m;
24  }
25
26  void saisir(void) {
27      int i;
28      for (i = 0; i < N; i++) {
29          printf("Plaque : ");
30          scanf("%s", parc[i].plaque);
31          do {
32              printf("Heures (1 a 24) : ");
33              scanf("%d", &parc[i].heures);
34          } while (parc[i].heures < 1 || parc[i].heures > 24);
35          parc[i].montant = calculer(parc[i].heures);
36          recette = recette + parc[i].montant;
37      }
38  }
39
40  int main() {
41      int i, longs = 0;
42      saisir();
43      for (i = 0; i < N; i++) {
44          if (parc[i].heures > 4)
45              longs++;
46      }
47      printf("Recette : %d FCFA\n", recette);
48      printf("Stationnements longs : %d\n", longs);
49      return 0;
50  }
```

